<?php
/** Proof — people, organizations, queues (tool surface): the resolve shape for `q` alone, who sees an address, the queue's holders versus a requester, workload against capacity. */
require __DIR__ . '/lib.php';
$F = dated(); $W = world(); $T = $F['tickets'];
echo "1. find_members\n";
$d = tdata(27, 'find_members', ['q' => 'Mar']);
ok($d === [['member_id' => 27, 'display_name' => 'SMOKE Marco']] || (is_array($d) && in_array(['member_id' => 27, 'display_name' => 'SMOKE Marco'], $d, true) && !has_key($d, 'email')), '`q` alone answers a plain list (member_id, display_name) — Marco by the start of a name');
$d = tdata(27, 'find_members', ['q' => 'arco']);
ok($d === [], 'a name matches at the start of a word, not inside it ("arco" finds nobody)');
$d = tdata(27, 'find_members', ['kind' => 'agent']);
ok(array_column($d['members'], 'member_id') === [40] || in_array(40, array_column($d['members'], 'member_id')), 'kind=agent lists the agent (Frontline)');
$d = tdata(27, 'find_members', ['queue_id' => $F['it']]);
$ids = array_column($d['members'], 'member_id'); sort($ids);
ok(in_array(27, $ids) && in_array(28, $ids) && !in_array(29, $ids), "queue_id=IT: Marco and Lena, not Colin (Facilities)");
$byId = array_column($d['members'], null, 'member_id');
ok($byId[27]['email'] === 'marco@example.invalid' || $byId[27]['email'] !== null, 'a person sees their own address') ;
ok($byId[28]['email'] === null, "and not another's");
$d = tdata(26, 'find_members', ['q' => 'Lena']);
ok(is_array($d) && count($d) === 1 && $d[0]['display_name'] === 'SMOKE Lena', 'a requester may look a person up by name too (names, not addresses)');
echo "2. find_requesters, requester_history\n";
$d = tdata(26, 'find_requesters', ['q' => 'priya']);
ok(is_array($d) && count($d) === 1 && $d[0]['display_name'] === 'SMOKE Priya' && !has_key($d, 'email'), 'a requester finds their own row (resolve shape, no address in it)');
$d = tdata(26, 'find_requesters', ['kind' => 'external']);
ok($d['requesters'] === [], 'and no other requester');
$d = tdata(27, 'find_requesters', ['q' => 'jo']);
ok(is_array($d) && count($d) >= 1 && $d[0]['display_name'] === 'SMOKE Jo', 'a queue holder finds Jo');
$d = tdata(27, 'find_requesters', ['organization_id' => $W['org']]);
$jo = array_values(array_filter($d['requesters'], fn ($r) => $r['display_name'] === 'SMOKE Jo'))[0] ?? null;
ok($jo !== null && $jo['email'] === 'jo@customer.invalid' && $jo['phone'] === '+1 555 0199' && $jo['ticket_count'] >= 10, "…with address, phone and ticket count ({$jo['ticket_count']})");
$d = tdata(27, 'requester_history', ['email' => 'jo@customer.invalid', 'limit' => 100]);
$visible = (int) val_as(27, "SELECT count(*) FROM mcp_tickets WHERE requester_id = :r AND merged_into_id IS NULL", ['r' => $W['jo']]);
ok(!isset($d['error']) && count($d['tickets']) === $visible && $visible >= 10, "requester_history: Jo's tickets as Marco sees them ($visible)");
ok($d['open_tickets'] === (int) val_as(27, "SELECT count(*) FROM mcp_tickets WHERE requester_id = :r AND merged_into_id IS NULL AND status_category IN " . OPEN_SQL, ['r' => $W['jo']]), 'and how many are open');
ok(array_values(array_filter($d['tickets'], fn ($t) => $t['number'] === num_of($T['it1'])))[0]['rating'] === 5, "the rating of a rated ticket (it1: 5)");
ok(isset($d['tickets'][0]['created_at_local']) && $d['timezone'] === 'UTC', 'times in UTC and in the caller\'s zone');
ok(tool(26, 'requester_history', ['requester_id' => $W['jo']])['error'], 'a requester asking for Jo\'s history: refused (not among those they may see)');
ok(tool(27, 'requester_history', [])['error'], 'no id and no email: asked which');
echo "3. find_organizations, find_queues\n";
$d = tdata(27, 'find_organizations', ['q' => 'smoke customer']);
ok(is_array($d) && $d === [['organization_id' => $W['org'], 'name' => 'SMOKE Customer Co']], '`q` alone: a plain list');
$d = tdata(27, 'find_organizations', ['organization_id' => $W['org']]);
$o = $d['organizations'][0] ?? [];
ok(($o['support_tier'] ?? '') === 'Gold' && in_array('customer.invalid', $o['domains'] ?? []) && $o['open_tickets'] === (int) val_as(27, "SELECT count(*) FROM mcp_tickets WHERE organization_id = :o AND status_category IN " . OPEN_SQL, ['o' => $W['org']]), 'in full: tier, domains, open ticket count');
$d = tdata(27, 'find_organizations', ['q' => 'customer.invalid']);
ok(count($d) === 1, 'found by domain too');
ok(tdata(26, 'find_organizations', ['q' => 'smoke customer']) === [], 'a requester outside it finds nothing');
$d = tdata(28, 'find_queues', ['include_members' => true]);
$by = array_column($d['queues'], null, 'queue_id');
ok(isset($by[$F['it']], $by[$F['fac']]) && $by[$F['it']]['mine'] === true && $by[$F['it']]['i_lead'] === true && $by[$F['fac']]['mine'] === false, 'Lena holds IT and leads it; Facilities is not hers');
ok(in_array(28, array_column($by[$F['it']]['members'], 'member_id')) && array_values(array_filter($by[$F['it']]['members'], fn ($m) => $m['member_id'] === 28))[0]['is_lead'] === true, 'include_members lists the queue with Lena as lead');
$d = tdata(27, 'find_queues', ['mine' => true]);
ok(array_column($d['queues'], 'queue_id') == [$F['it']] || in_array($F['it'], array_column($d['queues'], 'queue_id')) && !in_array($F['fac'], array_column($d['queues'], 'queue_id')), 'mine=true: Marco\'s queues, not Facilities');
$d = tdata(27, 'find_queues', ['q' => 'IT']);
ok($d === [['queue_id' => $F['it'], 'name' => 'SMOKE IT help']], '`q` alone: a plain list (queue_id, name)');
$d = tdata(26, 'find_queues', ['include_members' => true]);
ok(count($d['queues']) >= 1 && array_sum(array_map(fn ($q) => count($q['members'] ?? []), $d['queues'])) === 0, 'a requester sees the queues\' names and no members');
echo "4. agent_workload\n";
$d = tdata(28, 'agent_workload', []);
$marco = array_values(array_filter($d['workload'], fn ($r) => $r['member_id'] === 27 && $r['queue_id'] === $F['it']))[0] ?? null;
$openMarco = (int) val_as(28, "SELECT count(*) FROM mcp_tickets WHERE assignee_member_id = 27 AND merged_into_id IS NULL AND queue_id = :q AND status_category IN " . OPEN_SQL, ['q' => $F['it']]);
ok($marco !== null && $marco['open'] === $openMarco && $marco['capacity'] === 2 && $marco['availability'] === 'online' && $marco['over_capacity'] === true, "Marco: $openMarco open against a capacity of 2, online, over capacity");
$lena = array_values(array_filter($d['workload'], fn ($r) => $r['member_id'] === 28))[0] ?? null;
ok($lena !== null && $lena['availability'] === 'away' && $lena['capacity'] === null && $lena['over_capacity'] === false, 'Lena: away, no capacity');
ok(!has_key(tdata(28, 'agent_workload', ['include_agents' => false]), 'nothing') && array_filter(tdata(28, 'agent_workload', ['include_agents' => false])['workload'], fn ($r) => $r['kind'] === 'agent') === [], 'include_agents=false leaves the agents out');
ok(array_unique(array_column(tdata(27, 'agent_workload', [])['workload'], 'queue_id')) === [$F['it']], 'Marco sees IT\'s workload only');
ok(tool(26, 'agent_workload', [])['error'], 'a requester: refused (a queue holder\'s tool)');
finish();
